begin;
select no_plan();
insert into auth.users(id) values('aaaaaaaa-0000-4000-8000-000000000201');
insert into public.profiles(user_id,consent_account_at,consent_reading_at) values('aaaaaaaa-0000-4000-8000-000000000201',now(),now());
insert into public.subscription_state(user_id,expires_at,will_renew,period_type,has_history) values('aaaaaaaa-0000-4000-8000-000000000201',now()+interval '1 day',true,'NORMAL',true);
insert into public.reading_ai_policies(id,enabled,provider,model,fixed_price,currency,krw_per_currency,price_version,fx_version,fx_at)
values('22222222-0000-4000-8000-000000000201',true,'local','fixture',1,'KRW',1,'fixture','fixture',now());
select public.ai_budget_set(date_trunc('month',public.study_now() at time zone 'Asia/Seoul')::date,300000,299999,.8);
create function pg_temp.payload() returns jsonb language sql as $$ select '{"subject_id":"50000000-0000-4000-8000-000000000201","range_text":"fixture","origin":"home","object_paths":["aaaaaaaa-0000-4000-8000-000000000201/60000000-0000-4000-8000-000000000201/p0.jpg"]}'::jsonb $$;
create function pg_temp.result() returns jsonb language sql as $$ select '{"schema_version":2,"pages":[{"index":0,"items":[{"number":1,"mark":null,"confidence":null,"box":[0,0,1,1],"needs_review":true}]}]}'::jsonb $$;
select ok(public.reading_valid_result(pg_temp.result(),1),'A15 uncertain mark and missing confidence accepted as review-only');
select ok(not public.reading_valid_result('{}',1),'A02 missing required fields rejected');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,index}','null'),1),'A15 null page rejected');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,index}','1'),1),'A15 absent page rejected');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,items,0,number}','1.5'),1),'A15 fractional number rejected');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,items,0,mark}','"other"'),1),'A15 unknown mark rejected');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,items,0,confidence}','2'),1),'A15 confidence bound');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,items,0,box}','[1,0,0,1]'),1),'A15 inverted box');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,items,0,needs_review}','false'),1),'A15 cannot silently confirm');
select ok(not public.reading_valid_result(jsonb_set(pg_temp.result(),'{pages,0,items}',(pg_temp.result()#>'{pages,0,items}')||(pg_temp.result()#>'{pages,0,items}')),1),'A15 duplicate number');
select ok(not public.ai_valid_usage('[]'),'A18 non-object usage rejected');
select ok(not public.ai_valid_usage('{"requests":-1}'),'A19 negative units rejected');
select ok(not public.ai_valid_usage('{"images":1.2}'),'A19 fractional units rejected');
select ok(not public.ai_valid_usage('{"amount":0}'),'A18 worker cannot supply money');
select ok(not has_function_privilege('authenticated','public.ai_record_evidence(uuid,uuid,uuid,text,text,jsonb)','execute'),'A18 client cannot reconcile');
select ok(not has_table_privilege('authenticated','public.reading_ai_costs','SELECT'),'A17 cost ledger is private');
select is(public.reading_submit('aaaaaaaa-0000-4000-8000-000000000201','60000000-0000-4000-8000-000000000201',pg_temp.payload())->>'outcome','accepted','A17 existing quota reserves');
select is(public.reading_claim_job()->>'attempts','1','A15 attempt claimed');
select throws_ok($$select public.reading_ai_begin('aaaaaaaa-0000-4000-8000-000000000201','60000000-0000-4000-8000-000000000201',2)$$,'P0001','stale_attempt','A15 stale attempt cannot dispatch');
create temp table evidence as select public.reading_ai_begin('aaaaaaaa-0000-4000-8000-000000000201','60000000-0000-4000-8000-000000000201',1) as v;
select is((select v->>'claimed' from evidence),'true','A20 reading cost shares exact remaining budget');
select is(public.reading_ai_begin('aaaaaaaa-0000-4000-8000-000000000201','60000000-0000-4000-8000-000000000201',1)->>'claimed','false','A18 replay cannot re-execute');
select is((select count(*) from public.ai_point_lots),0::bigint,'A17 no points granted or charged to fake free reading');
select is((select reserved_krw from public.ai_budgets limit 1),1::numeric,'A20 one operating-cost reservation');
select throws_ok($$select public.ai_record_evidence(null,(v->>'cost_id')::uuid,(v->>'attempt_id')::uuid,'local','fixture','{}') from evidence$$,'P0001','invalid_usage_evidence','A18 missing units never zero');
select is(public.reading_finish_attempt('aaaaaaaa-0000-4000-8000-000000000201','60000000-0000-4000-8000-000000000201',2,'done',pg_temp.result())->>'outcome','noop','A15 late previous attempt cannot finish');
select is(public.reading_finish_attempt('aaaaaaaa-0000-4000-8000-000000000201','60000000-0000-4000-8000-000000000201',1,'done',pg_temp.result())->>'outcome','done','A15 current attempt finishes');
select public.ai_record_evidence(null,(v->>'cost_id')::uuid,(v->>'attempt_id')::uuid,'local','fixture','{"requests":1,"pages":1,"images":1,"crops":0,"elapsed_ms":10}') from evidence;
select is((select status from public.reading_ai_costs),'unknown','A19 nonzero policy stays unknown despite local receipt');
select public.reading_ai_reconcile((v->>'cost_id')::uuid,(v->>'attempt_id')::uuid,1,'{"requests":1,"pages":1,"images":1}') from evidence;
select public.reading_ai_reconcile((v->>'cost_id')::uuid,(v->>'attempt_id')::uuid,1,'{"requests":1,"pages":1,"images":1}') from evidence;
select is((select spent_krw from public.ai_budgets limit 1),1::numeric,'A18 actual evidence settles once');
select is((select reserved_krw from public.ai_budgets limit 1),0::numeric,'A19 reservation released only by settlement');
select is((select used from public.reading_quota limit 1),1,'A17 original quota charged once');
select is((select reserved from public.reading_quota limit 1),0,'A17 quota reservation resolved');
select * from finish();
rollback;
